import { describe, expect, it, vi } from 'vitest'

import {
	createOAuthAccountLinkRequest,
	createOAuthAccountSwitchLogin,
} from './oauth-link-action'
import { hashOAuthLinkSession } from '@/server/oauth-link-intent'

describe('OAuth account switch login', () => {
	it('signs out once and returns to email login for Discord', async () => {
		const signOut = vi.fn(async () => {})
		const switchLogin = createOAuthAccountSwitchLogin({ signOut })

		await expect(switchLogin()).resolves.toBeUndefined()
		expect(switchLogin).toHaveLength(0)
		expect(signOut).toHaveBeenCalledOnce()
		expect(signOut).toHaveBeenCalledWith({
			redirectTo: '/login?callbackUrl=/discord',
		})
	})
})

describe('OAuth account link request', () => {
	it('derives the target and binding from a fresh authenticated server session', async () => {
		const issueIntent = vi.fn(async () => ({
			rawToken: 'opaque-link-token',
			expiresAt: new Date('2026-08-09T12:10:00.000Z'),
		}))
		const writeIntentCookie = vi.fn()
		const request = createOAuthAccountLinkRequest({
			getAuthenticatedSession: vi.fn(async () => ({
				userId: 'session-user',
				sessionToken: 'fresh-session-token',
			})),
			findAccount: vi.fn(async () => null),
			issueIntent,
			writeIntentCookie,
		})

		await expect(request()).resolves.toEqual({ status: 'ready' })
		expect(issueIntent).toHaveBeenCalledWith({
			targetUserId: 'session-user',
			provider: 'discord',
			sessionBinding: hashOAuthLinkSession('fresh-session-token'),
		})
		expect(writeIntentCookie).toHaveBeenCalledWith({
			rawToken: 'opaque-link-token',
			expiresAt: new Date('2026-08-09T12:10:00.000Z'),
		})
	})

	it('ignores forged provider and user arguments', async () => {
		const issueIntent = vi.fn(async () => ({
			rawToken: 'opaque-link-token',
			expiresAt: new Date('2026-08-09T12:10:00.000Z'),
		}))
		const request = createOAuthAccountLinkRequest({
			getAuthenticatedSession: vi.fn(async () => ({
				userId: 'session-user',
				sessionToken: 'fresh-session-token',
			})),
			findAccount: vi.fn(async () => null),
			issueIntent,
			writeIntentCookie: vi.fn(),
		})

		await Reflect.apply(request, null, ['github', 'victim-user'])

		expect(request).toHaveLength(0)
		expect(issueIntent).toHaveBeenCalledWith(
			expect.objectContaining({
				targetUserId: 'session-user',
				provider: 'discord',
			}),
		)
	})

	it('does not persist or write a cookie without a valid session', async () => {
		const issueIntent = vi.fn()
		const writeIntentCookie = vi.fn()
		const request = createOAuthAccountLinkRequest({
			getAuthenticatedSession: vi.fn(async () => null),
			findAccount: vi.fn(),
			issueIntent,
			writeIntentCookie,
		})

		await expect(request()).resolves.toEqual({ status: 'unauthenticated' })
		expect(issueIntent).not.toHaveBeenCalled()
		expect(writeIntentCookie).not.toHaveBeenCalled()
	})

	it('does not issue another intent for an already linked session', async () => {
		const issueIntent = vi.fn()
		const request = createOAuthAccountLinkRequest({
			getAuthenticatedSession: vi.fn(async () => ({
				userId: 'session-user',
				sessionToken: 'fresh-session-token',
			})),
			findAccount: vi.fn(async () => ({ access_token: 'active-token' })),
			issueIntent,
			writeIntentCookie: vi.fn(),
		})

		await expect(request()).resolves.toEqual({ status: 'linked' })
		expect(issueIntent).not.toHaveBeenCalled()
	})

	it('issues a renewal intent when the same-owner account has stale credentials', async () => {
		const issueIntent = vi.fn(async () => ({
			rawToken: 'renewal-token',
			expiresAt: new Date('2026-08-09T12:10:00.000Z'),
		}))
		const request = createOAuthAccountLinkRequest({
			getAuthenticatedSession: vi.fn(async () => ({
				userId: 'session-user',
				sessionToken: 'fresh-session-token',
			})),
			findAccount: vi.fn(async () => ({ access_token: null })),
			issueIntent,
			writeIntentCookie: vi.fn(),
		})

		await expect(request()).resolves.toEqual({ status: 'ready' })
		expect(issueIntent).toHaveBeenCalledOnce()
	})
})

import { readFileSync } from 'node:fs'
import { describe, expect, it } from 'vitest'

const actionSource = readFileSync(
	new URL('./oauth-link-actions.ts', import.meta.url),
	'utf8',
)

describe('OAuth account link server action wiring', () => {
	it('accepts no caller-selected identity or provider', () => {
		expect(actionSource).toMatch(
			/export async function requestOAuthAccountLink\(\)\s*{/,
		)
		expect(actionSource).not.toContain(
			'function requestOAuthAccountLink(' + 'userId',
		)
		expect(actionSource).not.toContain(
			'function requestOAuthAccountLink(' + 'provider',
		)
		expect(actionSource).not.toContain('unlinkAccount')
	})

	it('uses the session-derived request handler and fixed Discord sign-in', () => {
		expect(actionSource).toContain('createOAuthAccountLinkRequest')
		expect(actionSource).toContain("await signIn('discord'")
		expect(actionSource).toContain("redirectTo: '/discord/redirect'")
	})
})

import { NextRequest, NextResponse } from 'next/server'
import { env } from '@/env.mjs'
import { withSkill } from '@/server/with-skill'
import { createSupportHandler } from '@skillrecordings/sdk/handler'

import { integration } from '../integration'

/**
 * Support Platform API Handler
 *
 * Handles requests from the Skill Recordings support platform:
 * - lookupUser: Find user by email
 * - getPurchases: Get user's purchase history
 * - revokeAccess: Revoke access after refund
 * - transferPurchase: Transfer license to new owner
 * - generateMagicLink: Create passwordless login link
 * - updateEmail: Change user's email
 * - updateName: Change user's display name
 *
 * All requests are authenticated via HMAC-SHA256 signature.
 */
export const POST = withSkill(async (request: NextRequest) => {
	// Check at request time, not build time
	if (!env.SUPPORT_WEBHOOK_SECRET) {
		return NextResponse.json(
			{ error: 'Support integration not configured' },
			{ status: 503 },
		)
	}

	const handler = createSupportHandler({
		integration,
		webhookSecret: env.SUPPORT_WEBHOOK_SECRET,
	})

	return handler(request)
})

import { createHash } from 'node:crypto'
import { couponSchema } from '@coursebuilder/core/schemas'
import { beforeEach, describe, expect, it, vi } from 'vitest'

const mocks = vi.hoisted(() => {
	const protectedMerchantCoupon = {
		id: 'merchant-prior-credit',
		identifier: 'stripe-prior-credit',
		merchantAccountId: 'merchant-account',
		type: 'special credit',
		status: 1,
		amountDiscount: 20_000,
		percentageDiscount: null,
	}
	const defaultMerchantCoupon = {
		id: 'merchant-intro',
		identifier: 'stripe-intro',
		merchantAccountId: 'merchant-account',
		type: 'special',
		status: 1,
		amountDiscount: 10_000,
		percentageDiscount: null,
	}
	const pppMerchantCoupon = {
		id: 'merchant-ppp-raw',
		type: 'ppp',
		status: 1,
		amountDiscount: null,
		percentageDiscount: 0.5,
	}
	const rawDeniedMerchantCoupons = [
		{
			id: 'merchant-special-raw',
			type: 'special',
			status: 1,
			amountDiscount: 5_000,
			percentageDiscount: null,
		},
		{
			id: 'merchant-bulk-raw',
			type: 'bulk',
			status: 1,
			amountDiscount: null,
			percentageDiscount: 0.2,
		},
		{
			id: 'merchant-stacked-raw',
			type: 'stacked',
			status: 1,
			amountDiscount: 15_000,
			percentageDiscount: null,
		},
		{
			id: 'merchant-upgrade-raw',
			type: 'upgrade',
			status: 1,
			amountDiscount: 15_000,
			percentageDiscount: null,
		},
		{
			id: 'merchant-credit-bulk-raw',
			type: 'special credit bulk',
			status: 1,
			amountDiscount: 20_000,
			percentageDiscount: null,
		},
	]
	const protectedCoupon = {
		id: 'coupon-prior-credit',
		merchantCouponId: protectedMerchantCoupon.id,
		restrictedToProductId: 'product-crash-course',
		fields: { exclusive: true },
		status: 1,
		expires: null,
		maxUses: -1,
		usedCount: 0,
	}
	const defaultCoupon = {
		id: 'coupon-intro',
		merchantCouponId: defaultMerchantCoupon.id,
		restrictedToProductId: 'product-crash-course',
		fields: {},
		status: 1,
		expires: null,
		maxUses: -1,
		usedCount: 0,
	}
	const expiredPublicCoupon = {
		...defaultCoupon,
		id: 'coupon-public-expired',
		expires: new Date('2020-01-01T00:00:00Z'),
	}
	const entitlement = {
		id: 'entitlement-prior-credit',
		userId: 'user-entitled',
		sourceType: 'COUPON',
		sourceId: protectedCoupon.id,
		entitlementType: 'entitlement-type-special-credit',
		deletedAt: null,
		expiresAt: null,
	}
	const getEntitlementsForUser = vi.fn()
	const adapter = {
		getMerchantCoupon: vi.fn(
			async (id: string) =>
				[
					protectedMerchantCoupon,
					defaultMerchantCoupon,
					pppMerchantCoupon,
					...rawDeniedMerchantCoupons,
				].find((coupon) => coupon.id === id) ?? null,
		),
		getCoupon: vi.fn(
			async (id: string) =>
				[protectedCoupon, defaultCoupon, expiredPublicCoupon].find(
					(coupon) => coupon.id === id,
				) ?? null,
		),
		getEntitlementTypeByName: vi.fn(async () => ({
			id: 'entitlement-type-special-credit',
		})),
		getEntitlementsForUser,
		getPurchasesForUser: vi.fn(async () => []),
		availableUpgradesForProduct: vi.fn(async () => []),
		getPriceForProduct: vi.fn(async () => ({ unitAmount: 299 })),
		getDefaultCoupon: vi.fn(async () => ({
			defaultCoupon,
			defaultMerchantCoupon,
		})),
		couponForIdOrCode: vi.fn(async () => null),
	}

	return {
		adapter,
		defaultMerchantCoupon,
		entitlement,
		formatPricesForProduct: vi.fn(),
		getEntitlementsForUser,
		getServerAuthSession: vi.fn(),
		protectedMerchantCoupon,
		pppMerchantCoupon,
		rawDeniedMerchantCoupons,
	}
})

vi.mock('@/db', () => ({
	courseBuilderAdapter: mocks.adapter,
	db: {
		query: {
			entitlementTypes: {
				findFirst: vi.fn(async () => ({
					id: 'entitlement-type-special-credit',
				})),
			},
			products: { findMany: vi.fn() },
		},
	},
}))
vi.mock('@/db/schema', () => ({ entitlementTypes: { name: 'name' } }))
vi.mock('@/server/auth', () => ({
	getServerAuthSession: mocks.getServerAuthSession,
}))
vi.mock('next/headers', () => ({
	headers: vi.fn(async () => new Headers({ 'x-vercel-ip-country': 'US' })),
}))
vi.mock('drizzle-orm', () => ({ eq: vi.fn(() => true) }))
vi.mock('@coursebuilder/commerce', () => ({
	formatPricesForProduct: mocks.formatPricesForProduct,
}))
vi.mock('@coursebuilder/commerce/props-for-commerce', () => ({
	propsForCommerce: vi.fn(),
}))

import { pricingRouter } from './pricing'

const caller = () =>
	pricingRouter.createCaller({
		db: null,
		session: null,
		ability: null,
		headers: new Headers(),
	} as never)

const formattedInput = {
	productId: 'product-crash-course',
	quantity: 1,
	merchantCoupon: {
		id: mocks.protectedMerchantCoupon.id,
		type: mocks.protectedMerchantCoupon.type,
	},
}

describe('pricing.formatted exclusive coupon authorization', () => {
	beforeEach(() => {
		vi.clearAllMocks()
		mocks.formatPricesForProduct.mockImplementation(async (input) => {
			const computedBulkCoupon = mocks.rawDeniedMerchantCoupons.find(
				(coupon) => coupon.type === 'bulk',
			)
			if (input.userId === 'user-ppp') {
				return {
					id: input.productId,
					calculatedPrice: 149.5,
					appliedMerchantCoupon: mocks.pppMerchantCoupon,
				}
			}
			if (input.quantity > 1) {
				return {
					id: input.productId,
					calculatedPrice: 500,
					appliedMerchantCoupon: computedBulkCoupon,
				}
			}
			return {
				id: input.productId,
				calculatedPrice:
					input.merchantCouponId === mocks.protectedMerchantCoupon.id
						? 99
						: 199,
				appliedMerchantCoupon:
					input.merchantCouponId === mocks.protectedMerchantCoupon.id
						? mocks.protectedMerchantCoupon
						: mocks.defaultMerchantCoupon,
			}
		})
	})

	it('falls back to the $199 default for a logged-out replay', async () => {
		mocks.getServerAuthSession.mockResolvedValue({ session: null })
		mocks.getEntitlementsForUser.mockResolvedValue([])

		const result = await caller().formatted(formattedInput)

		expect(result.calculatedPrice).toBe(199)
		expect(mocks.formatPricesForProduct).toHaveBeenCalledWith(
			expect.objectContaining({
				merchantCouponId: mocks.defaultMerchantCoupon.id,
				userId: undefined,
			}),
		)
	})

	it('falls back to the $199 default for a non-entitled session user', async () => {
		mocks.getServerAuthSession.mockResolvedValue({
			session: { user: { id: 'user-not-entitled' } },
		})
		mocks.getEntitlementsForUser.mockResolvedValue([])

		const result = await caller().formatted(formattedInput)

		expect(result.calculatedPrice).toBe(199)
		expect(mocks.formatPricesForProduct).toHaveBeenCalledWith(
			expect.objectContaining({
				merchantCouponId: mocks.defaultMerchantCoupon.id,
				userId: 'user-not-entitled',
			}),
		)
	})

	it.each(mocks.rawDeniedMerchantCoupons)(
		'strips a raw $type selector without site provenance',
		async (merchantCoupon) => {
			mocks.getServerAuthSession.mockResolvedValue({ session: null })
			mocks.getEntitlementsForUser.mockResolvedValue([])

			const result = await caller().formatted({
				productId: 'product-crash-course',
				quantity: 1,
				merchantCoupon: {
					id: merchantCoupon.id,
					type: merchantCoupon.type,
				},
			})

			expect(result.calculatedPrice).toBe(199)
			expect(mocks.formatPricesForProduct).toHaveBeenCalledWith(
				expect.objectContaining({
					merchantCouponId: mocks.defaultMerchantCoupon.id,
				}),
			)
		},
	)

	it('keeps a raw public selector with matching site provenance', async () => {
		mocks.getServerAuthSession.mockResolvedValue({ session: null })
		mocks.getEntitlementsForUser.mockResolvedValue([])

		const result = await caller().formatted({
			productId: 'product-crash-course',
			quantity: 1,
			couponId: 'coupon-intro',
			merchantCoupon: {
				id: mocks.defaultMerchantCoupon.id,
				type: mocks.defaultMerchantCoupon.type,
			},
		})

		expect(result.calculatedPrice).toBe(199)
		expect(mocks.formatPricesForProduct).toHaveBeenCalledWith(
			expect.objectContaining({
				merchantCouponId: mocks.defaultMerchantCoupon.id,
			}),
		)
	})

	it('strips a raw bulk selector and keeps server-computed bulk pricing', async () => {
		mocks.getServerAuthSession.mockResolvedValue({ session: null })
		mocks.getEntitlementsForUser.mockResolvedValue([])
		const rawBulkCoupon = mocks.rawDeniedMerchantCoupons.find(
			(coupon) => coupon.type === 'bulk',
		)

		const result = await caller().formatted({
			productId: 'product-crash-course',
			quantity: 5,
			merchantCoupon: {
				id: rawBulkCoupon?.id as string,
				type: 'bulk',
			},
		})

		expect(result.appliedMerchantCoupon?.type).toBe('bulk')
		expect(mocks.formatPricesForProduct).toHaveBeenCalledWith(
			expect.objectContaining({
				merchantCouponId: mocks.defaultMerchantCoupon.id,
				quantity: 5,
			}),
		)
	})

	it('rejects an inactive public site coupon without a merchant selector', async () => {
		mocks.getServerAuthSession.mockResolvedValue({ session: null })
		mocks.getEntitlementsForUser.mockResolvedValue([])

		const result = await caller().formatted({
			productId: 'product-crash-course',
			quantity: 1,
			couponId: 'coupon-public-expired',
		})

		expect(result.calculatedPrice).toBe(199)
		expect(mocks.formatPricesForProduct).toHaveBeenCalledWith(
			expect.objectContaining({
				merchantCouponId: mocks.defaultMerchantCoupon.id,
				usedCouponId: 'coupon-intro',
			}),
		)
	})

	it('strips raw PPP and keeps server-revalidated PPP pricing', async () => {
		mocks.getServerAuthSession.mockResolvedValue({
			session: { user: { id: 'user-ppp' } },
		})
		mocks.getEntitlementsForUser.mockResolvedValue([])

		const result = await caller().formatted({
			productId: 'product-crash-course',
			quantity: 1,
			merchantCoupon: {
				id: mocks.pppMerchantCoupon.id,
				type: mocks.pppMerchantCoupon.type,
			},
		})

		expect(result.appliedMerchantCoupon?.type).toBe('ppp')
		expect(mocks.formatPricesForProduct).toHaveBeenCalledWith(
			expect.objectContaining({
				merchantCouponId: mocks.defaultMerchantCoupon.id,
				userId: 'user-ppp',
			}),
		)
	})

	it('preserves the $99 path for the entitled session user', async () => {
		mocks.getServerAuthSession.mockResolvedValue({
			session: { user: { id: mocks.entitlement.userId } },
		})
		mocks.getEntitlementsForUser.mockResolvedValue([mocks.entitlement])

		const result = await caller().formatted(formattedInput)

		expect(result.calculatedPrice).toBe(99)
		expect(mocks.formatPricesForProduct).toHaveBeenCalledWith(
			expect.objectContaining({
				merchantCouponId: mocks.protectedMerchantCoupon.id,
				usedCouponId: 'coupon-prior-credit',
				userId: mocks.entitlement.userId,
			}),
		)
	})

	it('prices a signed-out evergreen coupon after the real adapter schema normalizes its row', async () => {
		vi.useFakeTimers()
		vi.setSystemTime(new Date('2026-09-24T18:00:00.000Z'))
		try {
			const issueAt = '2026-09-24T16:00:00.000Z'
			const expiresAt = '2026-09-29T06:59:59.000Z'
			const journeyId = 'evergreen-offer:drovr:contact-smoke-1'
			const idempotencyKey = `${journeyId}:coupon.issue`
			const couponId = `eoj-coupon:${createHash('sha256').update(idempotencyKey).digest('hex')}`
			const merchant = {
				id: 'merchant-evergreen',
				type: 'special',
				status: 1,
				amountDiscount: 10_000,
			}
			const row = couponSchema.parse({
				id: couponId,
				code: null,
				organizationId: null,
				createdAt: new Date(issueAt),
				expires: new Date(expiresAt),
				fields: {
					exclusive: true,
					evergreenOffer: {
						format: 1,
						issue: {
							type: 'IssueCoupon',
							idempotencyKey,
							journeyId,
							contactId: 'contact-smoke-1',
							issueAt,
							expiresAt,
							terms: {
								productId: 'product-ma254',
								currency: 'USD',
								amountOffCents: 10_000,
								maxUses: 1,
								exclusive: true,
							},
							deadlineTimeZone: {
								type: 'BrowserEntryHeader',
								headerName: 'x-vercel-ip-timezone',
								timeZone: 'America/Los_Angeles',
								capturedAt: issueAt,
							},
						},
						binding: { type: 'AwaitingVerifiedUser' },
					},
				},
				maxUses: 1,
				default: false,
				merchantCouponId: merchant.id,
				status: 1,
				usedCount: 0,
				percentageDiscount: null,
				amountDiscount: 10_000,
				restrictedToProductId: 'product-ma254',
			})
			// The production adapter parses with this schema: NULL becomes zero.
			expect(row.percentageDiscount).toBe(0)
			mocks.getServerAuthSession.mockResolvedValue({ session: null })
			// This one-shot fixture uses the wider real adapter shape rather than
			// the narrow public/default fixtures inferred by this test's mocks.
			mocks.adapter.getCoupon.mockResolvedValueOnce(row as never)
			mocks.adapter.getMerchantCoupon.mockResolvedValueOnce({
				...merchant,
				percentageDiscount: null,
			} as never)
			mocks.adapter.getDefaultCoupon.mockResolvedValueOnce(null as never)
			mocks.adapter.couponForIdOrCode.mockResolvedValueOnce({
				...row,
				merchantCoupon: merchant,
			} as never)
			mocks.formatPricesForProduct.mockImplementationOnce(async (input) => ({
				id: input.productId,
				calculatedPrice: input.merchantCouponId === merchant.id ? 199 : 299,
				usedCouponId: input.usedCouponId ?? null,
				appliedMerchantCoupon:
					input.merchantCouponId === merchant.id ? merchant : null,
			}))

			const result = await caller().formatted({
				productId: 'product-ma254',
				quantity: 1,
				couponId,
			})
			expect(result.calculatedPrice).toBe(199)
			expect(result.usedCouponId).toBe(couponId)
			expect(result.appliedMerchantCoupon?.id).toBe(merchant.id)
			expect(mocks.formatPricesForProduct).toHaveBeenCalledWith(
				expect.objectContaining({
					merchantCouponId: merchant.id,
					usedCouponId: couponId,
				}),
			)
		} finally {
			vi.useRealTimers()
		}
	})
})

