						})),
					}),
					then: (resolve: any) => resolve(resolveValue),
					[Symbol.iterator]: () => resolveValue[Symbol.iterator](),
				}),
			}),
			limit: vi.fn().mockImplementation(() => ({
				then: (resolve: any) => resolve(resolveValue),
				[Symbol.iterator]: () => resolveValue[Symbol.iterator](),
			})),
		}
		return obj
	})
}

