				operation: 'apply',
				allowWrite: false,
				previewToken: 'not-used',
			}),
		)

		expect(response.status).toBe(400)
		expect(deps.store.createIntent).not.toHaveBeenCalled()
	})
})

import type { ConnectableOAuthProvider } from './oauth-link-cookie'
import { hashOAuthLinkSession } from '@/server/oauth-link-intent'

type AuthenticatedSession = {
	userId: string
	sessionToken: string
}

type OAuthAccountSwitchLoginDependencies = {
	signOut: (options: { redirectTo: string }) => Promise<unknown>
}

type OAuthAccountLinkRequestDependencies = {
	getAuthenticatedSession: () =>
		| AuthenticatedSession
		| null
		| Promise<AuthenticatedSession | null>
	findAccount: (input: {
		userId: string
		provider: ConnectableOAuthProvider
	}) =>
		| { access_token?: string | null }
		| null
		| undefined
		| PromiseLike<{ access_token?: string | null } | null | undefined>
	issueIntent: (input: {
		targetUserId: string
		provider: ConnectableOAuthProvider
		sessionBinding: string
	}) => Promise<{ rawToken: string; expiresAt: Date }>
	writeIntentCookie: (input: {
		rawToken: string
		expiresAt: Date
	}) => void | Promise<void>
}

export function createOAuthAccountSwitchLogin({
	signOut,
}: OAuthAccountSwitchLoginDependencies) {
	return async function switchOAuthAccountLogin() {
		await signOut({ redirectTo: '/login?callbackUrl=/discord' })
	}
}

/**
 * The request takes no caller identity or provider. Discord and the target user
 * both come from trusted server state.
 */
export function createOAuthAccountLinkRequest({
	getAuthenticatedSession,
	findAccount,
	issueIntent,
	writeIntentCookie,
}: OAuthAccountLinkRequestDependencies) {
	return async function requestOAuthAccountLink() {
		const session = await getAuthenticatedSession()
		if (!session) return { status: 'unauthenticated' as const }

		const provider = 'discord' satisfies ConnectableOAuthProvider
		const existingAccount = await findAccount({
			userId: session.userId,
			provider,
		})
		if (existingAccount?.access_token) return { status: 'linked' as const }

		try {
			const issued = await issueIntent({
				targetUserId: session.userId,
				provider,
				sessionBinding: hashOAuthLinkSession(session.sessionToken),
			})
			await writeIntentCookie(issued)
			return { status: 'ready' as const }
		} catch {
			return { status: 'denied' as const }
		}
	}
}

'use server'

import { cookies } from 'next/headers'
import { redirect } from 'next/navigation'
import { courseBuilderAdapter, db } from '@/db'
import { accounts } from '@/db/schema'
import {
	clearLegacyOAuthLinkCookies,
	writeOAuthLinkIntentCookie,
} from '@/lib/oauth-link-cookie'
import { oauthLinkIntentService } from '@/server/oauth-link-intent-drizzle'
import { createAuthenticatedOAuthLinkSessionResolver } from '@/server/oauth-link-session'
import { and, eq } from 'drizzle-orm'

import {
	createOAuthAccountLinkRequest,
	createOAuthAccountSwitchLogin,
} from './oauth-link-action'
import { signIn, signOut } from '@/server/auth'

const getSessionAndUser =
	courseBuilderAdapter.getSessionAndUser?.bind(courseBuilderAdapter)
if (!getSessionAndUser) {
	throw new Error('OAuth linking requires database sessions')
}

const getAuthenticatedSession = createAuthenticatedOAuthLinkSessionResolver({
	getCookieStore: cookies,
	getSessionAndUser,
})

const switchLogin = createOAuthAccountSwitchLogin({ signOut })

const requestLink = createOAuthAccountLinkRequest({
	getAuthenticatedSession,
	findAccount: ({ userId, provider }) =>
		db.query.accounts.findFirst({
			where: and(eq(accounts.userId, userId), eq(accounts.provider, provider)),
		}),
	issueIntent: (input) => oauthLinkIntentService.issue(input),
	writeIntentCookie: async (input) => {
		const cookieStore = await cookies()
		clearLegacyOAuthLinkCookies(cookieStore)
		writeOAuthLinkIntentCookie(cookieStore, input)
	},
})

/**
 * Clears the current session before the customer chooses the AI Hero login
 * that already owns the Discord account.
 */
export async function switchOAuthAccountLogin() {
	await switchLogin()
}

/**
 * Starts a Discord link from a fresh database session. The action accepts no
 * provider or user identity from the browser.
 */
export async function requestOAuthAccountLink() {
	const result = await requestLink()
	if (result.status === 'unauthenticated') {
		redirect('/login?callbackUrl=/discord')
	}
	if (result.status === 'linked') redirect('/discord/redirect')
	if (result.status === 'denied') redirect('/discord?link=denied')

	await signIn('discord', { redirectTo: '/discord/redirect' })
	redirect('/discord?link=denied')
}

